insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder familiar é exercido em igualdade de condições pelo pai e pela mãe, na forma da legislação civil, e qualquer deles pode recorrer ao juiz para resolver divergência.', '["Igualdade entre pai e mãe.","Divergência resolvida pelo juiz."]'::jsonb, '["Igualdade de condições entre os genitores."]'::jsonb, 'Se os pais divergem sobre a escola, qualquer um pode pedir decisão judicial.', '["Assertiva que dá a decisão final ao pai erra: a divergência vai ao juiz."]'::jsonb, '[{"termo":"Poder familiar","significado":"Conjunto de direitos e deveres dos pais sobre os filhos menores."}]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos pais incumbe o dever de sustento, guarda, convivência, assistência material e afetiva e educação dos filhos menores, além de cumprir e fazer cumprir as determinações judiciais. Mãe e pai, ou responsáveis, têm direitos iguais e deveres e responsabilidades compartilhados, resguardado o direito de transmissão familiar de suas crenças e culturas.', '["Sustento, guarda, convivência, assistência e educação.","Cumprir e fazer cumprir ordens judiciais.","Responsabilidades compartilhadas."]'::jsonb, '["Inclui a assistência AFETIVA."]'::jsonb, 'Os pais devem matricular o filho na escola e acompanhar sua vida escolar.', '["Assertiva que limita o dever dos pais ao sustento material erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A falta ou a carência de recursos materiais não é motivo suficiente para a perda ou suspensão do poder familiar. Se não houver outro motivo, a criança é mantida na família de origem, que será incluída em serviços e programas oficiais de proteção e apoio. A condenação criminal do pai ou da mãe não implica destituição do poder familiar, salvo condenação por crime doloso sujeito a pena de reclusão contra quem detém igualmente o poder familiar ou contra o filho, a filha ou outro descendente.', '["Pobreza não justifica perda do poder familiar.","Família de origem incluída em programas de apoio.","Condenação criminal só leva à destituição em hipóteses específicas."]'::jsonb, '["ATUALIZAÇÃO: o §2º foi reforçado por lei posterior.","A carência de recursos NÃO basta para destituir."]'::jsonb, 'A família pobre recebe apoio do Estado e não perde o filho por isso.', '["Assertiva que autoriza a destituição do poder familiar pela mera pobreza erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A perda e a suspensão do poder familiar são decretadas judicialmente, em procedimento contraditório, nos casos previstos na legislação civil e quando houver descumprimento injustificado dos deveres do art. 22.', '["Decretação judicial.","Procedimento contraditório.","Casos da lei civil e descumprimento dos deveres."]'::jsonb, '["Só o juiz decreta, em contraditório."]'::jsonb, 'A perda do poder familiar exige processo com defesa dos pais.', '["Assertiva que permite ao Conselho Tutelar decretar a perda do poder familiar erra."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Família natural é a comunidade formada pelos pais ou qualquer deles e seus descendentes. Família extensa ou ampliada é a que vai além do núcleo de pais e filhos, formada por parentes próximos com quem a criança convive e mantém vínculos de afinidade e afetividade.', '["Família natural.","Família extensa ou ampliada com vínculos de afinidade e afetividade."]'::jsonb, '["A família extensa exige vínculos de afinidade e afetividade, além do parentesco."]'::jsonb, 'A avó com quem a criança convive integra a família extensa.', '["Assertiva que define a família extensa só pelo parentesco, sem vínculo afetivo, erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os filhos havidos fora do casamento podem ser reconhecidos pelos pais, em conjunto ou separadamente, no termo de nascimento, por testamento, escritura ou outro documento público. O reconhecimento pode preceder o nascimento ou suceder ao falecimento do filho, se deixar descendentes.', '["Formas de reconhecimento.","Reconhecimento antes do nascimento ou após o falecimento do filho com descendentes."]'::jsonb, '["Pode ser feito por testamento."]'::jsonb, 'O pai reconhece o filho em escritura pública.', '["Assertiva que veda o reconhecimento antes do nascimento erra."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O reconhecimento do estado de filiação é direito personalíssimo, indisponível e imprescritível, exercido contra os pais ou seus herdeiros, sem restrição, em segredo de Justiça.', '["Direito personalíssimo, indisponível e imprescritível.","Exercido contra pais ou herdeiros.","Segredo de Justiça."]'::jsonb, '["IMPRESCRITÍVEL."]'::jsonb, 'O filho pode pedir o reconhecimento da paternidade a qualquer tempo.', '["Assertiva que sujeita o reconhecimento de filiação a prazo prescricional erra."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A colocação em família substituta se dá por guarda, tutela ou adoção, independentemente da situação jurídica da criança. Sempre que possível, a criança é previamente ouvida por equipe interprofissional, e o adolescente maior de doze anos deve consentir em audiência. A preferência recai sobre a família extensa, considerando grau de parentesco e afinidade, e os grupos de irmãos devem ser colocados sob a mesma família, salvo exceções. A colocação de criança indígena ou quilombola observa suas tradições e a ouvida de equipe especializada.', '["Guarda, tutela ou adoção.","Oitiva da criança e consentimento do maior de doze anos.","Preferência pela família extensa.","Irmãos juntos.","Respeito a tradições de indígenas e quilombolas."]'::jsonb, '["Maior de doze anos: CONSENTIMENTO em audiência.","ATUALIZAÇÃO: regras de oitiva e de povos tradicionais vieram de leis posteriores."]'::jsonb, 'A adolescente de treze anos precisa consentir na colocação em família substituta.', '["Assertiva que dispensa o consentimento do maior de doze anos erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se defere colocação em família substituta a quem revele incompatibilidade com a natureza da medida ou não ofereça ambiente familiar adequado.', '["Incompatibilidade com a medida.","Ambiente inadequado."]'::jsonb, '["Requisito de idoneidade do ambiente."]'::jsonb, 'Quem vive em ambiente violento não recebe a guarda.', '["Assertiva que dispensa a avaliação do ambiente familiar erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-29'
