select u.id, u.content_sha256, 'Ao assumir a guarda ou a tutela, o responsável presta compromisso de bem e fielmente desempenhar o encargo, mediante termo nos autos.', '["Compromisso formal por termo nos autos."]'::jsonb, '["Termo de compromisso."]'::jsonb, 'O tutor assina o termo de compromisso no processo.', '["Assertiva que dispensa o compromisso do guardião erra."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-32'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A guarda obriga a prestar assistência material, moral e educacional à criança ou ao adolescente, e dá ao detentor o direito de opor-se a terceiros, inclusive aos pais. Destina-se a regularizar a posse de fato, podendo ser deferida liminar ou incidentalmente em tutela e adoção, exceto na adoção por estrangeiros, e excepcionalmente fora desses casos para situações peculiares. A guarda confere à criança a condição de dependente para todos os fins, inclusive previdenciários.', '["Assistência material, moral e educacional.","Oposição a terceiros, inclusive aos pais.","Regularização da posse de fato.","Condição de dependente."]'::jsonb, '["Pode ser oposta até aos pais.","Não cabe guarda liminar em adoção por estrangeiros."]'::jsonb, 'O avô com a guarda pode incluir o neto como dependente.', '["Assertiva que impede o guardião de se opor aos pais da criança erra."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público estimula, por assistência jurídica, incentivos fiscais e subsídios, o acolhimento, sob a forma de guarda, de criança ou adolescente afastado do convívio familiar. A inclusão em acolhimento familiar tem preferência sobre o institucional, sempre com caráter temporário e excepcional. A pessoa ou casal cadastrado no programa pode receber a criança mediante guarda.', '["Estímulo ao acolhimento familiar.","Preferência pelo acolhimento familiar.","Caráter temporário e excepcional."]'::jsonb, '["Acolhimento FAMILIAR tem preferência sobre o institucional."]'::jsonb, 'A criança afastada da família é acolhida por uma família cadastrada antes de ir a um abrigo.', '["Assertiva que dá preferência ao acolhimento institucional erra."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A tutela é deferida, nos termos da lei civil, a pessoa de até dezoito anos incompletos. O deferimento da tutela pressupõe a prévia decretação da perda ou suspensão do poder familiar e implica necessariamente o dever de guarda.', '["Tutela para quem tem menos de dezoito anos.","Pressupõe perda ou suspensão do poder familiar.","Implica dever de guarda."]'::jsonb, '["ATUALIZAÇÃO: a idade foi ajustada para dezoito anos incompletos.","Tutela exige prévia perda ou suspensão do poder familiar."]'::jsonb, 'O tutor só é nomeado depois da decisão sobre o poder familiar.', '["Assertiva que dispensa a prévia perda do poder familiar para a tutela erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-36'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tutor nomeado por testamento ou documento autêntico deve, no prazo de trinta dias após a abertura da sucessão, ingressar com pedido para o controle judicial do ato, seguindo o procedimento dos arts. 165 a 170. A tutela só é deferida à pessoa indicada na disposição de última vontade se comprovado que a medida é vantajosa ao tutelando e que não há outra pessoa em melhores condições de assumi-la.', '["Prazo de trinta dias após a abertura da sucessão.","Controle judicial do ato.","Vantagem ao tutelando e inexistência de pessoa em melhores condições."]'::jsonb, '["Prazo de trinta dias."]'::jsonb, 'O tutor indicado em testamento pede o controle judicial em trinta dias.', '["Assertiva que fixa em sessenta dias o prazo do tutor testamentário erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 36"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-37'
