select u.id, u.content_sha256, 'O adotando deve ter, no máximo, dezoito anos à data do pedido, salvo se já estiver sob a guarda ou tutela dos adotantes.', '["Limite de dezoito anos à data do pedido.","Exceção: guarda ou tutela anterior."]'::jsonb, '["O que conta é a idade à data do PEDIDO."]'::jsonb, 'O jovem sob tutela dos adotantes pode ser adotado mesmo após os dezoito anos.', '["Assertiva que impede qualquer adoção após dezoito anos erra: há exceção para guarda ou tutela."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-40'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção atribui ao adotado a condição de filho, com os mesmos direitos e deveres, inclusive sucessórios, desligando-o de qualquer vínculo com os pais e parentes biológicos, salvo os impedimentos matrimoniais. Na adoção do filho do cônjuge ou companheiro, mantêm-se os vínculos com ele. O direito sucessório é recíproco entre adotado, seus descendentes, adotante, seus ascendentes, descendentes e colaterais até o quarto grau.', '["Condição de filho, com todos os direitos.","Desligamento dos pais biológicos, salvo impedimentos matrimoniais.","Exceção na adoção do filho do cônjuge.","Direito sucessório recíproco."]'::jsonb, '["Desligamento total, mas permanecem os impedimentos matrimoniais."]'::jsonb, 'O adotado herda do adotante como filho.', '["Assertiva que mantém o vínculo com os pais biológicos após a adoção erra."]'::jsonb, '[]'::jsonb, '["Art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-41'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Podem adotar os maiores de dezoito anos, independentemente do estado civil. Não podem adotar os ascendentes e os irmãos do adotando. A adoção conjunta exige que os adotantes sejam casados civilmente ou vivam em união estável, e o adotante deve ser pelo menos dezesseis anos mais velho que o adotando. Divorciados, separados e ex-companheiros podem adotar conjuntamente, se acordarem sobre guarda e visitas e o estágio de convivência tiver começado na constância da sociedade conjugal.', '["Maiores de dezoito anos, qualquer estado civil.","Vedada a adoção por ascendentes e irmãos.","Adoção conjunta por casados ou em união estável.","Diferença mínima de dezesseis anos.","Divorciados e ex-companheiros em condições específicas."]'::jsonb, '["ATUALIZAÇÃO: idade reduzida para dezoito anos pelo Código Civil de 2002 e regras da Lei de Adoção.","Diferença mínima de dezesseis anos."]'::jsonb, 'Uma pessoa solteira de trinta anos pode adotar um adolescente de doze.', '["Assertiva que exige vinte e um anos para adotar erra: são dezoito anos."]'::jsonb, '[]'::jsonb, '["Art. 43"]'::jsonb, 'under_review', 'claude'
