insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção será deferida quando apresentar reais vantagens para o adotando e fundar-se em motivos legítimos.', '["Reais vantagens para o adotando.","Motivos legítimos."]'::jsonb, '["Critério central: vantagem para o adotando."]'::jsonb, 'O juiz nega a adoção feita por interesse puramente patrimonial.', '["Assertiva que dispensa a análise de vantagens para o adotando erra."]'::jsonb, '[]'::jsonb, '["Art. 39"]'::jsonb, 'under_review', 'claude'
