select u.id, u.content_sha256, 'Enquanto não prestar contas de sua administração e saldar o seu alcance, o tutor ou curador não pode adotar o pupilo ou curatelado.', '["Impedimento enquanto não houver prestação de contas."]'::jsonb, '["Proteção do patrimônio do pupilo."]'::jsonb, 'O tutor com contas pendentes não pode adotar o pupilo.', '["Assertiva que permite ao tutor com contas pendentes adotar o pupilo erra."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
