insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A morte dos adotantes não restabelece o poder familiar dos pais naturais.', '["Morte dos adotantes não restabelece o poder familiar anterior."]'::jsonb, '["Reforça a irrevogabilidade."]'::jsonb, 'Com a morte dos adotantes, os pais biológicos não retomam o poder familiar.', '["Assertiva que restabelece o poder familiar dos pais naturais com a morte dos adotantes erra."]'::jsonb, '[]'::jsonb, '["Art. 39"]'::jsonb, 'under_review', 'claude'
