on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade judiciária mantém, em cada comarca ou foro regional, um registro de crianças e adolescentes em condições de serem adotados e outro de pessoas interessadas na adoção. A inscrição é deferida após consulta aos órgãos técnicos e oitiva do Ministério Público, e a de postulantes é precedida de preparação psicossocial e jurídica. Crianças não podem ser adotadas por quem não esteja habilitado, salvo hipóteses legais, como o pedido de adoção unilateral e o de parente com vínculos de afinidade.', '["Dois registros: adotáveis e pretendentes.","Consulta aos órgãos técnicos e ao Ministério Público.","Preparação psicossocial e jurídica.","Exceções à exigência de cadastro."]'::jsonb, '["ATUALIZAÇÃO: o cadastro nacional e a preparação foram reforçados pela Lei de Adoção.","Regra: adoção só por quem está habilitado no cadastro."]'::jsonb, 'Os interessados fazem curso de preparação antes de entrar no cadastro.', '["Assertiva que dispensa a preparação psicossocial dos pretendentes erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-50'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se adoção internacional aquela em que o pretendente tem residência habitual em país signatário da Convenção de Haia e deseja adotar criança em outro país signatário. A adoção internacional de criança brasileira só ocorre se comprovado que a colocação em família adotiva é a solução adequada, que foram esgotadas as possibilidades de colocação em família adotiva brasileira e que, em se tratando de adolescente, ele foi consultado e preparado.', '["Residência habitual em país signatário da Convenção de Haia.","Medida de última linha: esgotadas as possibilidades nacionais.","Consulta e preparo do adolescente."]'::jsonb, '["Adoção internacional só quando esgotadas as possibilidades NACIONAIS.","Preferência de brasileiros residentes no exterior sobre estrangeiros."]'::jsonb, 'A criança só é adotada por casal de outro país depois de esgotadas as tentativas no Brasil.', '["Assertiva que dá prioridade a estrangeiros sobre candidatos nacionais erra."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-51'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção internacional segue o procedimento dos arts. 165 a 170, com adaptações: o interessado estrangeiro pede habilitação à Autoridade Central do país de acolhida, que emite relatório com informações sobre sua identidade e capacidade jurídica, o encaminha à Autoridade Central Estadual e esta, após análise, expede o laudo de habilitação, com validade e regras próprias de renovação.', '["Habilitação perante a Autoridade Central do país de acolhida.","Relatório e laudo de habilitação.","Validade e renovação."]'::jsonb, '["Procedimento com adaptações para a adoção internacional."]'::jsonb, 'O casal estrangeiro é habilitado pelas autoridades antes de poder adotar.', '["Assertiva que dispensa a habilitação na adoção internacional erra."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-52'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedado, sob pena de responsabilidade e descredenciamento, o repasse de recursos de organismos estrangeiros que intermedeiam adoção internacional a organismos nacionais ou a pessoas físicas. Eventuais repasses só podem ocorrer via Fundo dos Direitos da Criança e do Adolescente, sujeitos às deliberações do respectivo Conselho.', '["Vedado o repasse de recursos a organismos nacionais ou pessoas físicas.","Repasses somente via Fundo."]'::jsonb, '["Repasses SOMENTE via Fundo dos Direitos da Criança e do Adolescente."]'::jsonb, 'Um organismo estrangeiro só doa recursos por meio do Fundo.', '["Assertiva que permite o repasse direto a pessoas físicas erra."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
