insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o Brasil é o país de acolhida, a decisão da autoridade do país de origem é conhecida pela Autoridade Central Estadual que processou a habilitação, que comunica a Autoridade Central Federal e adota as providências para o Certificado de Naturalização Provisório. A decisão só deixa de ser reconhecida se a adoção for manifestamente contrária à ordem pública ou ao interesse superior da criança.', '["Reconhecimento da decisão estrangeira pela Autoridade Central Estadual.","Certificado de Naturalização Provisório.","Recusa só se contrária à ordem pública ou ao interesse da criança."]'::jsonb, '["Recusa apenas em caso de violação manifesta."]'::jsonb, 'A decisão do país de origem é reconhecida e a criança recebe a naturalização provisória.', '["Assertiva que exige nova sentença brasileira sempre erra."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
