insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito à educação, visando ao pleno desenvolvimento da pessoa, ao preparo para a cidadania e à qualificação para o trabalho, com igualdade de condições para acesso e permanência na escola, direito de ser respeitado por educadores, de contestar critérios avaliativos, de organização em entidades estudantis e de acesso à escola pública e gratuita próxima de casa, com vagas no mesmo estabelecimento para irmãos. Os pais têm direito de ter ciência do processo pedagógico e de participar da definição das propostas educacionais.', '["Desenvolvimento, cidadania e qualificação.","Igualdade de acesso e permanência.","Direito de contestar avaliações e de organização estudantil.","Escola pública, gratuita e próxima de casa.","Ciência dos pais sobre o processo pedagógico."]'::jsonb, '["Escola próxima de casa e vaga no mesmo estabelecimento para irmãos.","Pais têm direito à ciência do processo pedagógico."]'::jsonb, 'Dois irmãos têm direito a vaga na mesma escola próxima da residência.', '["Assertiva que nega ao estudante o direito de contestar critérios de avaliação erra."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
