insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os responsáveis por estabelecimentos de bilhar, sinuca ou congênere ou por casas de jogos, isto é, as que realizem apostas, ainda que eventualmente, cuidam para que não entrem nem permaneçam crianças e adolescentes, afixando aviso para orientação do público.', '["Vedada a entrada e permanência de crianças e adolescentes.","Aviso afixado."]'::jsonb, '["Casas de jogos: aposta, ainda que eventual."]'::jsonb, 'A casa de sinuca afixa o aviso de proibição a menores.', '["Assertiva que permite a permanência de adolescentes em casas de jogos desde que acompanhados erra."]'::jsonb, '[]'::jsonb, '["Art. 258"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-80'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É proibida a venda à criança ou ao adolescente de armas, munições e explosivos; bebidas alcoólicas; produtos cujos componentes possam causar dependência física ou psíquica; fogos de estampido e de artifício, exceto os incapazes de provocar dano; revistas e publicações impróprias; e bilhetes lotéricos e equivalentes.', '["Armas, munições e explosivos.","Bebidas alcoólicas.","Produtos que causem dependência.","Fogos de estampido e artifício, com exceção.","Publicações impróprias.","Bilhetes lotéricos."]'::jsonb, '["Seis incisos de proibição de venda.","ATUALIZAÇÃO: leis posteriores criaram tipos penais específicos de venda a crianças."]'::jsonb, 'A loja não pode vender bebida alcoólica a um adolescente.', '["Assertiva que permite a venda de bilhete lotérico ao adolescente acompanhado erra."]'::jsonb, '[]'::jsonb, '["Art. 243"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-81'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É proibida a hospedagem de criança ou adolescente em hotel, motel, pensão ou estabelecimento congênere, salvo se autorizado ou acompanhado pelos pais ou responsável.', '["Vedada a hospedagem desacompanhada.","Exceção: autorização ou acompanhamento dos pais ou responsável."]'::jsonb, '["Autorização OU acompanhamento afasta a vedação."]'::jsonb, 'O adolescente com autorização dos pais pode se hospedar no hotel.', '["Assertiva que proíbe a hospedagem mesmo acompanhada pelos pais erra."]'::jsonb, '[]'::jsonb, '["Art. 250"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-82'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma criança ou adolescente menor de dezesseis anos pode viajar para fora da comarca onde reside desacompanhado dos pais ou responsáveis sem expressa autorização judicial. A autorização é dispensada em comarca contígua da mesma unidade da Federação ou região metropolitana, ou quando acompanhado de ascendente ou colateral maior até o terceiro grau, ou de pessoa maior expressamente autorizada pelo pai, mãe ou responsável.', '["Menor de dezesseis anos precisa de autorização para sair da comarca.","Dispensas: comarca contígua, parente maior, pessoa autorizada.","Autorização judicial pode ser válida por até dois anos."]'::jsonb, '["Regra aplica-se ao menor de dezesseis anos.","Dispensas em comarcas contíguas e com acompanhante autorizado."]'::jsonb, 'A adolescente de quinze anos viaja com a tia maior, comprovado o parentesco.', '["Assertiva que exige autorização judicial para qualquer viagem de adolescente erra: há dispensas."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-83'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na viagem ao exterior, a autorização é dispensável se a criança ou o adolescente estiver acompanhado de ambos os pais ou responsável, ou viajar com um dos pais autorizado expressamente pelo outro por documento com firma reconhecida.', '["Dispensa se acompanhado de ambos os pais ou responsável.","Dispensa se com um dos pais e autorização do outro com firma reconhecida."]'::jsonb, '["Firma reconhecida na autorização do outro genitor."]'::jsonb, 'A criança viaja com a mãe e leva autorização do pai com firma reconhecida.', '["Assertiva que dispensa a firma reconhecida na autorização do outro genitor erra."]'::jsonb, '[]'::jsonb, '["Art. 85"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-84'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sem prévia e expressa autorização judicial, nenhuma criança ou adolescente nascido em território nacional pode sair do País em companhia de estrangeiro residente ou domiciliado no exterior.', '["Autorização judicial prévia e expressa.","Estrangeiro residente ou domiciliado no exterior."]'::jsonb, '["Exige autorização JUDICIAL, não só dos pais."]'::jsonb, 'A criança brasileira só viaja com estrangeiro residente fora com autorização do juiz.', '["Assertiva que dispensa a autorização judicial se os pais concordarem erra."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-85'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A política de atendimento dos direitos da criança e do adolescente é feita por um conjunto articulado de ações governamentais e não governamentais da União, dos estados, do Distrito Federal e dos municípios.', '["Ações articuladas.","Governamentais e não governamentais.","Todos os entes federativos."]'::jsonb, '["Política ARTICULADA entre os entes e a sociedade."]'::jsonb, 'Município, estado e ONGs atuam juntos em um programa de acolhimento.', '["Assertiva que atribui a política de atendimento somente à União erra."]'::jsonb, '[]'::jsonb, '["Art. 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-86'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São linhas de ação da política de atendimento as políticas sociais básicas; os serviços e programas de assistência social; os serviços especiais de prevenção e atendimento médico e psicossocial às vítimas de negligência, maus-tratos, exploração, abuso, crueldade e opressão; a proteção jurídico-social por entidades de defesa dos direitos; e a política de estímulo ao acolhimento familiar, entre outras.', '["Políticas sociais básicas.","Assistência social.","Atendimento às vítimas de violência.","Proteção jurídico-social.","Estímulo ao acolhimento familiar."]'::jsonb, '["ATUALIZAÇÃO: o rol foi ampliado por leis posteriores sobre busca de desaparecidos e acolhimento familiar."]'::jsonb, 'O município mantém serviço psicossocial para vítimas de abuso.', '["Assertiva que restringe as linhas de ação às políticas de saúde erra."]'::jsonb, '[]'::jsonb, '["Art. 86"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-87'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São diretrizes da política de atendimento a municipalização do atendimento; a criação de conselhos municipais, estaduais e nacional dos direitos da criança e do adolescente, órgãos deliberativos e controladores com participação popular paritária; a criação e manutenção de programas específicos; a manutenção de fundos vinculados aos conselhos; a integração operacional dos órgãos do Judiciário, Ministério Público, Defensoria, segurança pública e assistência social; e a mobilização da opinião pública.', '["Municipalização.","Conselhos deliberativos e controladores com participação paritária.","Fundos vinculados aos conselhos.","Integração operacional dos órgãos."]'::jsonb, '["Conselhos de direitos são deliberativos e controladores, com participação PARITÁRIA.","Municipalização é a primeira diretriz."]'::jsonb, 'O Conselho Municipal dos Direitos delibera sobre o uso do fundo.', '["Assertiva que torna os conselhos de direitos meramente consultivos erra: são deliberativos e controladores."]'::jsonb, '[{"termo":"Municipalização","significado":"Descentralização do atendimento para o nível municipal."}]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-88'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A função de membro dos Conselhos dos Direitos da Criança e do Adolescente é considerada de interesse público relevante e não é remunerada. Cada ente da Federação disciplina, por lei, a perda da função de conselheiro, respeitado o art. 89-A.', '["Interesse público relevante.","Não remunerada.","Perda da função disciplinada em lei de cada ente."]'::jsonb, '["Conselheiro de DIREITOS não é remunerado; o conselheiro tutelar é remunerado.","Não confundir Conselho de Direitos com Conselho Tutelar."]'::jsonb, 'O representante da sociedade civil no Conselho de Direitos atua sem remuneração.', '["Assertiva que prevê remuneração aos membros do Conselho dos Direitos erra."]'::jsonb, '[]'::jsonb, '["Art. 89-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-89'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São deveres fundamentais dos membros dos Conselhos dos Direitos promover a defesa dos direitos das crianças e dos adolescentes, respeitar a Constituição e as leis, zelar pelo prestígio do Conselho e exercer a função com dignidade e respeito aos pares, entre outros. A violação desses deveres pode levar à perda da função, na forma da lei de cada ente.', '["Defesa dos direitos da infância.","Cumprimento da Constituição e das leis.","Zelo pelo prestígio do Conselho."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O conselheiro que age com improbidade pode perder a função.', '["Assertiva que dispensa deveres funcionais dos conselheiros de direitos erra."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-89-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de atendimento são responsáveis pela manutenção das próprias unidades e pelo planejamento e execução de programas de proteção e socioeducativos, em regime de orientação e apoio sociofamiliar, apoio socioeducativo em meio aberto, colocação familiar, acolhimento institucional, prestação de serviços à comunidade, liberdade assistida, semiliberdade e internação. Os programas devem ser inscritos no Conselho Municipal dos Direitos.', '["Responsabilidade pela manutenção e execução dos programas.","Oito regimes de atendimento.","Inscrição dos programas no Conselho Municipal."]'::jsonb, '["Oito regimes: de orientação sociofamiliar à internação.","ATUALIZAÇÃO: acolhimento institucional substituiu a antiga referência a abrigo."]'::jsonb, 'A ONG inscreve seu programa de liberdade assistida no Conselho Municipal.', '["Assertiva que dispensa a inscrição dos programas no Conselho Municipal erra."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-90'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

